const Particle = ParticleModule.default || ParticleModule;

describe('Particle.applyBehaviours', () => {
  test('calls applyBehaviour on each truthy behaviour with correct args in order', () => {
    const p = new Particle();
    const calls = [];

    const b1 = {
      applyBehaviour: (particle, time, index) => {
        calls.push({ id: 1, particle, time, index });
      },
    };

    const b2 = {
      applyBehaviour: (particle, time, index) => {
        calls.push({ id: 2, particle, time, index });
      },
    };

    const b3 = {
      applyBehaviour: (particle, time, index) => {
        calls.push({ id: 3, particle, time, index });
      },
    };

    p.behaviours = [b1, null, b2, false, b3];

    p.applyBehaviours(12.34, 7);

    expect(calls.length).toBe(3);
    expect(calls[0].id).toBe(1);
    expect(calls[0].time).toBe(12.34);
    expect(calls[0].index).toBe(7);
    expect(calls[1].id).toBe(2);
    expect(calls[2].id).toBe(3);
    expect(calls.every((c) => c.particle === p)).toBe(true);
  });

  test('handles empty or only falsy behaviours without throwing', () => {
    const p = new Particle();
    p.behaviours = [];

    // Should not throw
    p.applyBehaviours(1, 2);

    // Now with a mix of falsy values and a real behaviour
    const spy = jest.fn();
    const realB = { applyBehaviour: spy };
    p.behaviours = [false, null, undefined, realB];

    p.applyBehaviours(3, 4);
    expect(spy).toHaveBeenCalledTimes(1);
    const lastCall = spy.mock.calls[0];
    expect(lastCall.length).toBe(3);
    expect(lastCall[0]).toBe(p);
    expect(lastCall[1]).toBe(3);
    expect(lastCall[2]).toBe(4);
  });
});

