describe('Particle.removeBehaviour', () => {
  test('removes existing behaviour from behaviours array and does not mutate the removed object', () => {
    const p = new Particle({});
    const b1 = { id: 'b1' };
    const b2 = { id: 'b2' };
    p.behaviours.push(b1, b2);
    p.removeBehaviour(b1);
    expect(p.behaviours).toEqual([b2]);
    // The code assigns parents to the removed array, not to the behaviour object
    expect(b1.parents).toBeUndefined();
  });

  test('does nothing when behaviour is not found in the array', () => {
    const p = new Particle({});
    const b1 = { id: 'b1' };
    p.behaviours.push(b1);
    const notInList = { id: 'not' };
    p.removeBehaviour(notInList);
    expect(p.behaviours).toEqual([b1]);
  });
});

