import RandomDrift from '../../../src/behaviour/RandomDrift.js';

describe('RandomDrift.reset', () => {
  test('sets panFoce to the normalized force and assigns delay', () => {
    const instance = Object.create(RandomDrift.prototype);
    const sentinel = { sentinel: true };
    instance.normalizeForce = () => sentinel;

    RandomDrift.prototype.reset.call(instance, 3, 4, 7);

    expect(instance.panFoce).toBe(sentinel);
    expect(instance.delay).toBe(7);
  });

  test('passes the original vector to normalizeForce', () => {
    const instance = Object.create(RandomDrift.prototype);
    let capturedVec = null;
    instance.normalizeForce = (vec) => {
      capturedVec = vec;
      return vec;
    };

    RandomDrift.prototype.reset.call(instance, -1, 2, 9);

    expect(capturedVec).toBeDefined();
    // The vector passed to normalizeForce should have x = driftX and y = driftY
    expect(capturedVec.x).toBe(-1);
    expect(capturedVec.y).toBe(2);
    // And panFoce should be the same object returned by normalizeForce
    expect(instance.panFoce).toBe(capturedVec);
    expect(instance.delay).toBe(9);
  });
});

