import Rectangle from '../../../src/math/Rectangle';

describe('Rectangle.contains', () => {
  test('returns true for a point inside the rectangle', () => {
    const rect = new Rectangle(0, 0, 10, 10);
    expect(rect.contains(5, 5)).toBe(true);
  });

  test('returns true for boundary points on left and top edges', () => {
    const rect = new Rectangle(2, 3, 6, 4); // left=2, right=8, top=3, bottom=7
    expect(rect.contains(2, 3)).toBe(true);
  });

  test('returns true for boundary points on right and bottom edges', () => {
    const rect = new Rectangle(2, 3, 6, 4); // right=8, bottom=7
    expect(rect.contains(8, 7)).toBe(true);
  });

  test('returns false for points outside the rectangle', () => {
    const rect = new Rectangle(0, 0, 5, 5);
    expect(rect.contains(-1, 0)).toBe(false); // left of rectangle
    expect(rect.contains(0, -1)).toBe(false); // above rectangle
    expect(rect.contains(6, 0)).toBe(false); // right of rectangle
    expect(rect.contains(0, 6)).toBe(false); // below rectangle
  });

  test('handles zero width and height', () => {
    const rect = new Rectangle(5, 7, 0, 0);
    expect(rect.contains(5, 7)).toBe(true);
    expect(rect.contains(5, 6)).toBe(false);
    expect(rect.contains(6, 7)).toBe(false);
  });
});

