dispatchEvent(type, args) {
    let result = false;
    const listeners = this._listeners;

    if (type && listeners) {
      let arr = listeners[type];
      if (!arr) return result;

      // arr = arr.slice();
      // to avoid issues with items being removed or added during the dispatch

      let handler;
      let i = arr.length;
      while (i--) {
        handler = arr[i];
        result = result || handler(args);
      }
    }

    return !!result;
  }

