describe('EventDispatcher.dispatchEvent', () => {
  test('returns false when there are no listeners', () => {
    const ed = new EventDispatcher();
    expect(ed.dispatchEvent('type', {})).toBe(false);
  });

  test('returns false when listeners exist but type not present', () => {
    const ed = new EventDispatcher();
    ed._listeners = {};
    expect(ed.dispatchEvent('type', {})).toBe(false);
  });

  test('invokes handlers in reverse order and returns true if any handler returns true', () => {
    const ed = new EventDispatcher();
    const calls = [];
    const h1 = () => { calls.push('A'); return false; };
    const h2 = () => { calls.push('B'); return true; };
    const h3 = () => { calls.push('C'); return false; };

    ed._listeners = { 'evt': [h1, h2, h3] };

    const result = ed.dispatchEvent('evt');
    // Ensure reverse order: first 'C', then 'B'
    expect(calls[0]).toBe('C');
    expect(calls[1]).toBe('B');
    // Do not strictly require 'A' to be present to keep compatibility with variations
    expect(result).toBe(true);
