    const fx = 10;
    const fy = -5;
    const expected = { normalized: true };

    const normalizeSpy = jest.spyOn(Force.prototype, 'normalizeForce').mockImplementation((vec) => {
      expect(vec).toBeTruthy();
      if ('x' in vec) {
        expect(vec.x).toBeCloseTo(fx);
      }
      if ('y' in vec) {
        expect(vec.y).toBeCloseTo(fy);
      }
      return expected;
    });

    const life = 2;
    const f = new Force(fx, fy, life, null);
    f.reset(fx, fy, life, null);

    expect(f.force).toBe(expected);
    normalizeSpy.mockRestore();
  });

  test('should call super.reset when life is truthy', () => {
    const fx = 1;
    const fy = 2;

    // Spy on the base class reset
    const Base = Object.getPrototypeOf(Force.prototype).constructor;
    const baseResetSpy = jest.spyOn(Base.prototype, 'reset').mockImplementation(function(life, easing) {
      // store on instance to help assertions if needed
      this._resetCalledWith = { life, easing };
    });

    // Ensure normalizeForce returns a sentinel to avoid side effects
    const sentinel = {};
    const normalizeSpy = jest.spyOn(Force.prototype, 'normalizeForce').mockImplementation((vec) => sentinel);

    const life = 5;
    const f = new Force(fx, fy, life, null);
    f.reset(fx, fy, life, null);

    // There should be at least one call to base.reset due to reset invocation
    expect(baseResetSpy).toHaveBeenCalled();
    // The last call should be with (life, easing)
    const calls = baseResetSpy.mock.calls;
    expect(calls[calls.length - 1]).toEqual([life, null]);

    baseResetSpy.mockRestore();
    normalizeSpy.mockRestore();
  });

  test('should not call super.reset when life is falsy', () => {
    const fx = 3;
    const fy = 4;

    const Base = Object.getPrototypeOf(Force.prototype).constructor;
