    const life = 0;
    const f = new Force(fx, fy, life, null);
    const beforeCalls = baseResetSpy.mock.calls.length;

    f.reset(fx, fy, life, null);

    const afterCalls = baseResetSpy.mock.calls.length;
    expect(afterCalls).toBe(beforeCalls);
  });
});

