      addEventListener(event, handler) {
        this.calls.push({ event, handler });
      }
    }

    const proton = new FakeProton();

    // Create a renderer instance without invoking the constructor to avoid side effects
    const renderer = Object.create(BaseRenderer.prototype);

    // Prepare unique sentinel handlers
    const hProtonUpdate = { id: 'protonUpdate' };
    const hProtonUpdateAfter = { id: 'protonUpdateAfter' };
    const hEmitterAdded = { id: 'emitterAdded' };
    const hEmitterRemoved = { id: 'emitterRemoved' };
    const hParticleCreated = { id: 'particleCreated' };
    const hParticleUpdate = { id: 'particleUpdate' };
    const hParticleDead = { id: 'particleDead' };

    // Attach sentinel handlers to the instance
    renderer._protonUpdateHandler = hProtonUpdate;
    renderer._protonUpdateAfterHandler = hProtonUpdateAfter;
    renderer._emitterAddedHandler = hEmitterAdded;
    renderer._emitterRemovedHandler = hEmitterRemoved;
    renderer._particleCreatedHandler = hParticleCreated;
    renderer._particleUpdateHandler = hParticleUpdate;
    renderer._particleDeadHandler = hParticleDead;

    // Execute the method under test
    renderer.init(proton);

    // Validate that seven event listeners were registered in the correct order with correct handlers
    expect(proton.calls.length).toBe(7);

    const expectedEvents = [
      'PROTON_UPDATE',
      'PROTON_UPDATE_AFTER',
      'EMITTER_ADDED',
      'EMITTER_REMOVED',
      'PARTICLE_CREATED',
      'PARTICLE_UPDATE',
      'PARTICLE_DEAD'
    ];

    const expectedHandlers = [
      hProtonUpdate,
      hProtonUpdateAfter,
      hEmitterAdded,
      hEmitterRemoved,
      hParticleCreated,
      hParticleUpdate,
      hParticleDead
    ];

    for (let i = 0; i < expectedEvents.length; i++) {
      expect(proton.calls[i].event).toBe(expectedEvents[i]);
      expect(proton.calls[i].handler).toBe(expectedHandlers[i]);
    }

    // Ensure the parent reference was set
    expect(renderer.parent).toBe(proton);
  });
});

